PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user',active INTEGER NOT NULL DEFAULT 1,balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0),created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS plans(id INTEGER PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>=0),credits INTEGER NOT NULL CHECK(credits>0),active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),name TEXT NOT NULL,idea TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,status TEXT DEFAULT 'draft',style TEXT DEFAULT 'modern',public INTEGER DEFAULT 0,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS builds(id TEXT PRIMARY KEY,project_id TEXT REFERENCES projects(id),status TEXT DEFAULT 'queued',error TEXT,created TEXT DEFAULT CURRENT_TIMESTAMP,started TEXT,finished TEXT,html TEXT);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),plan_id INTEGER REFERENCES plans(id),amount INTEGER NOT NULL,currency TEXT DEFAULT 'usd',credits INTEGER NOT NULL,status TEXT DEFAULT 'pending',provider TEXT,provider_ref TEXT UNIQUE,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ledger(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),delta INTEGER NOT NULL,reason TEXT NOT NULL,reference TEXT UNIQUE NOT NULL,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS listings(id INTEGER PRIMARY KEY,owner_id INTEGER REFERENCES users(id),project_id TEXT REFERENCES projects(id),name TEXT NOT NULL,description TEXT NOT NULL,category TEXT DEFAULT 'Apps',status TEXT DEFAULT 'pending',created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deployments(id TEXT PRIMARY KEY,project_id TEXT REFERENCES projects(id),build_id TEXT REFERENCES builds(id),status TEXT DEFAULT 'pending',url TEXT,error TEXT,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,actor INTEGER,action TEXT NOT NULL,target TEXT,created TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attempts(key TEXT PRIMARY KEY,count INTEGER DEFAULT 0,reset INTEGER NOT NULL);
INSERT OR IGNORE INTO plans VALUES(1,'Spark','1 web app build · free hosting · free subdomain · free store listing',500,1,1);
INSERT OR IGNORE INTO plans VALUES(2,'Launch','5 builds or revisions · free hosting · free subdomain · free store listing',1900,5,1);
INSERT OR IGNORE INTO plans VALUES(3,'Studio','15 builds or revisions · free hosting · free subdomain · free store listing',4900,15,1);
INSERT OR IGNORE INTO settings VALUES('ai_model','gpt-4.1-mini');
INSERT OR IGNORE INTO settings VALUES('builds_enabled','1');
INSERT OR IGNORE INTO settings VALUES('stripe_enabled','0');
INSERT OR IGNORE INTO settings VALUES('paystack_enabled','0');
INSERT OR IGNORE INTO settings VALUES('flutterwave_enabled','0');
INSERT OR IGNORE INTO settings VALUES('registration_enabled','1');
CREATE TABLE IF NOT EXISTS designs(project_id TEXT PRIMARY KEY REFERENCES projects(id),layout TEXT NOT NULL DEFAULT '[]',sketch TEXT,background TEXT DEFAULT '#f8f7ff',accent TEXT DEFAULT '#7047eb',updated TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deliveries(project_id TEXT PRIMARY KEY REFERENCES projects(id),due TEXT NOT NULL,status TEXT DEFAULT 'scheduled',note TEXT DEFAULT '',updated TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),message TEXT NOT NULL,read INTEGER DEFAULT 0,created TEXT DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO settings VALUES('delivery_days','7');
UPDATE plans SET name='AnyApps Complete',description='One app project · 5 builds or revisions · free web hosting · free subdomain · free Africa Apps Store listing',price=99900,credits=5 WHERE id=1 AND name='Spark';
UPDATE plans SET active=0 WHERE id IN (2,3) AND name IN ('Launch','Studio');
CREATE TABLE IF NOT EXISTS order_projects(order_id TEXT PRIMARY KEY REFERENCES orders(id),project_id TEXT NOT NULL REFERENCES projects(id),delivery_days INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS api_credentials(name TEXT PRIMARY KEY,ciphertext TEXT,enabled INTEGER NOT NULL DEFAULT 1,updated_by INTEGER REFERENCES users(id),updated TEXT DEFAULT CURRENT_TIMESTAMP,last_test TEXT,tested TEXT);
